mkdir -p src/lib && cat > src/lib/email.ts <<'EOF'
const RESEND_URL = "https://api.resend.com/emails";

type Email = { to: string; subject: string; html: string; text: string };

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

export function appUrl(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

async function sendEmail({ to, subject, html, text }: Email): Promise<void> {
  const apiKey = process.env.RESEND_API_KEY;
  const from = process.env.EMAIL_FROM;
  if (!apiKey || !from) {
    // No provider configured (local dev): log instead of failing.
    console.warn(`[email] RESEND_API_KEY/EMAIL_FROM not set; skipping "${subject}" to ${to}`);
    return;
  }
  const res = await fetch(RESEND_URL, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({ from, to, subject, html, text }),
  });
  if (!res.ok) {
    throw new Error(`Email send failed (${res.status}): ${await res.text()}`);
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const name = escapeHtml(user.name);
  return sendEmail({
    to: user.email,
    subject: "Welcome to Notely",
    text: `Hi ${user.name},\n\nWelcome to Notely! Get started: ${appUrl()}/dashboard\n`,
    html: `<p>Hi ${name},</p><p>Welcome to Notely! <a href="${appUrl()}/dashboard">Open your dashboard</a>.</p>`,
  });
}

export function sendPasswordResetEmail(user: { email: string; name: string }, token: string) {
  const link = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  return sendEmail({
    to: user.email,
    subject: "Reset your Notely password",
    text: `Hi ${user.name},\n\nReset your password (link valid for 1 hour): ${link}\n\nIf you didn't request this, ignore this email.\n`,
    html: `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${link}">Reset your password</a>. The link is valid for 1 hour.</p><p>If you didn't request this, ignore this email.</p>`,
  });
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  // Email failure must not fail signup.
  await sendWelcomeEmail(user).catch((err) => console.error("[email] welcome failed", err));
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Stored by SHA-256 hash so a leaked store doesn't expose usable tokens. In-memory like `users`.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (t: string) => createHash("sha256").update(t).digest("hex");

// Always resolves without revealing whether the email is registered.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email === email.trim().toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token).catch((err) =>
    console.error("[email] password reset failed", err),
  );
}

// Validates and consumes a reset token (single use). Returns the user, or undefined if invalid/expired.
// TODO: setting the new password belongs to the caller once credentials exist.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
EOF
sed -i '' '1i\
import { createHash, randomBytes } from "node:crypto";\
import { sendPasswordResetEmail, sendWelcomeEmail } from "./email";\

' src/lib/users.ts
cat > .env.example <<'EOF'
# Transactional email (Resend — https://resend.com)
RESEND_API_KEY=re_placeholder_replace_me
# Must be on a domain verified in Resend
EMAIL_FROM="Notely <noreply@example.com>"
# Public base URL used in email links
APP_URL=http://localhost:3000
EOF
sed -i '' 's|^\.env\*$|.env*\n!.env.example|' .gitignore
npx tsc --noEmit && npm run lint 2>&1 | tail -5; git status --short

